from scipy.optimize import least_squares
def mk(p):
    w=p[0]
    return (p[1]+p[2]*np.cos(w*t)+p[3]*np.sin(w*t)+p[4]*x+p[5]*v+p[6]*x**2+p[7]*x**3+p[8]*v*np.abs(v)+p[9]*x*v)
best=None
for w0 in np.linspace(0.3,6,40):
    p0=np.zeros(10); p0[0]=w0
    try:
        r=least_squares(lambda p: mk(p)-dv_dt, p0)
        if best is None or r.cost<best.cost: best=r
    except Exception as e: pass
print(best.x, np.mean(best.fun**2)/np.var(dv_dt))

